import {
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  Link,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon, ArrowForwardIcon } from "../../utils/iconMap";

interface SpecialtiesSectionProps {
  onViewPrograms: (specialtyId: string) => void;
}

export default function SpecialtiesSection({ onViewPrograms }: SpecialtiesSectionProps) {
  const { specialties, sections } = masterData;

  return (
    <Box sx={{ py: { xs: 5, md: 8 }, bgcolor: "#FAFBFD" }}>
      <Container maxWidth="lg">
        <Box sx={{ textAlign: "center", mb: 4 }}>
          <Typography
            variant="h4"
            sx={{ fontWeight: 800, color: "#0A2540", mb: 1, fontSize: { xs: "1.5rem", md: "2rem" } }}
          >
            {sections.specialties.title}
          </Typography>
          <Typography sx={{ color: "text.secondary", maxWidth: 560, mx: "auto" }}>
            {sections.specialties.subtitle}
          </Typography>
        </Box>

        <Grid container spacing={2.5}>
          {specialties.map((specialty) => {
            const Icon = getIcon(specialty.icon);
            return (
              <Grid key={specialty.id} size={{ xs: 12, sm: 6, md: 3 }}>
                <Card
                  sx={{
                    height: "100%",
                    borderRadius: 2,
                    transition: "transform 0.2s, box-shadow 0.2s",
                    "&:hover": {
                      transform: "translateY(-4px)",
                      boxShadow: "0 8px 24px rgba(0, 86, 210, 0.12)",
                    },
                  }}
                >
                  <CardContent sx={{ p: 2.5 }}>
                    <Stack spacing={1.5}>
                      <Box
                        sx={{
                          width: 48,
                          height: 48,
                          borderRadius: 1.5,
                          bgcolor: "#E8F1FF",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                        }}
                      >
                        <Icon sx={{ color: "primary.main", fontSize: 26 }} />
                      </Box>
                      <Typography sx={{ fontWeight: 700, color: "#0A2540", fontSize: 16 }}>
                        {specialty.name}
                      </Typography>
                      <Link
                        component="button"
                        underline="none"
                        onClick={() => onViewPrograms(specialty.id)}
                        sx={{
                          display: "inline-flex",
                          alignItems: "center",
                          gap: 0.5,
                          color: "primary.main",
                          fontWeight: 600,
                          fontSize: 14,
                          cursor: "pointer",
                          alignSelf: "flex-start",
                          "&:hover": { color: "primary.dark" },
                        }}
                      >
                        View Programs <ArrowForwardIcon sx={{ fontSize: 16 }} />
                      </Link>
                    </Stack>
                  </CardContent>
                </Card>
              </Grid>
            );
          })}
        </Grid>
      </Container>
    </Box>
  );
}
